#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p audiobooks/demo .runtime/check-audio
/usr/bin/say -v Milena -r 150 -o audiobooks/demo/01.aiff 'Это первая часть проверочной книги. Пока она звучит, можно позвать помощника и попросить поставить книгу на паузу. Можно узнать место остановки, выбрать другую книгу или продолжить эту. Сохранённое место остаётся у каждой книги своё. Сейчас первая часть закончится и начнётся вторая.'
/usr/bin/say -v Milena -r 150 -o audiobooks/demo/02.aiff 'Это вторая часть проверочной книги. Переход между файлами произошёл автоматически. Попробуйте поставить книгу на паузу, закрыть приложение и открыть его снова. Затем попросите продолжить. Эта небольшая запись создана специально для проверки помощника.'
/usr/bin/say -v Milena -r 150 -o audiobooks/demo/walk.aiff 'Представьте неспешную прогулку по осеннему парку. Под ногами тихо шуршат листья. Где-то рядом ветер качает ветви, а издалека доносится лай собаки. На скамейке можно остановиться, послушать звуки вокруг и никуда не торопиться. У этой книги своё сохранённое место.'
/usr/bin/say -v Milena -r 160 -o .runtime/check-audio/list.aiff 'Джарвис, какие у меня книги?'
/usr/bin/say -v Milena -r 160 -o .runtime/check-audio/chat.aiff 'Джарвис, расскажи короткую добрую историю.'
